class Model:
    def __init__(self):
        self.count = 0
        self.views = []
    def subscribe(self, v):
        self.views.append(v)
    def set(self, n):
        self.count = n
        for v in self.views:
            print(v(self))     # the model announces; views redraw

def text_view(m):
    return "text: count=" + str(m.count)

def bar_view(m):
    return "bar: " + "#" * m.count

def controller(m, events):
    for e in events:
        if e == "+":
            m.set(m.count + 1)
        else:
            m.set(m.count - 1)

m = Model()
m.subscribe(text_view)
m.subscribe(bar_view)
controller(m, ["+", "+", "-"])

