def server(req, book):
    # tiny REST-ish contract: GET reads, POST books, PATCH arrives
    if req == "GET":
        return "200 count=" + str(book["n"])
    if req == "POST":
        book["n"] += 1
        return "201 count=" + str(book["n"])
    if req == "PATCH":
        return "204 arrived"
    return "400"
book = {"n": 2}
for req in ["GET", "POST", "PATCH", "GET"]:
    print(req, "->", server(req, book))
# experiment: resend the POST twice (networks retry!). What happens to count?
