# BROKEN: the catalog's trait -> pattern wiring is crossed.
# A dataflow need (stream) gets a UI pattern; a UI need gets a pipeline.
RULES = [
    ("pipe-filter", "ui"),
    ("mvc", "stream"),
    ("client-server", "shared"),
]

def select(traits):
    for name, key in RULES:
        if traits.get(key, False):
            return name
    return "layered"

SCENARIOS = [
    ("S1", {"stream": True, "ui": False, "shared": False, "remote": False}),
    ("S2", {"shared": True, "remote": True, "stream": False, "ui": False}),
    ("S3", {"ui": True, "stream": False, "shared": False, "remote": False}),
]
EXPECTED = {"S1": "pipe-filter", "S2": "client-server", "S3": "mvc"}

hits = 0
for sid, traits in SCENARIOS:
    pick = select(traits)
    print(sid + ": " + pick)
    if pick == EXPECTED[sid]:
        hits += 1
print("matched: %d/%d" % (hits, len(SCENARIOS)))
